Section.CodeCell:
Console.WriteLine("Hello from .NET running in your browser.");
Console.WriteLine($"The shared world currently contains {world.Count} entities.");

var marker = world.Create(HList.From(
    new TourMessage("The next cell can find this entity.")));

Notebook.Render("Render is separate from console output.");

public readonly record struct TourMessage(string Text);

var found = 0;
foreach (var entity in world.Query(Matchers.Of<TourMessage>())) {
    Console.WriteLine(entity.Get<TourMessage>().Text);
    found++;
}

Console.WriteLine($"Found {found} message entity.");
Notebook.Render(new string('*', 12));

var carried = world.Count;
Console.WriteLine($"Replay start: {carried} {(carried == 1 ? "entity" : "entities")} carried over from the cells above.");
foreach (var entity in world.Query(Matchers.Of<TourMessage>())) {
    Console.WriteLine($"  still here: {entity.Get<TourMessage>().Text}");
}
Notebook.Render("One run, three cells: the scope replays from the top.");

var found = 0;
foreach (var entity in world.Query(Matchers.Of<TourMessage>())) {
    found++;
}
Console.WriteLine($"Found {found} TourMessage entities — this cell's world starts empty.");
Notebook.Render(found == 0
    ? "Isolated: this cell's world starts empty."
    : "Unexpected — scope isolation failed.");

public readonly record struct TourMessage(string Text);
